function serviceScene(group,title,body){return `<div class="service-experience expertise-page" data-service-scene style="--service-color:${palette[shapes.findIndex(s=>s.id===group)]};--field-tone:${fieldColours[Math.max(0,shapes.findIndex(s=>s.id===group))%3]}">${body}</div>`;}
function expertiseHero(title,description,{label,group='vergi',back='/hizmetler/',backLabel='Tüm hizmetler',target='#kapsam',action='Çalışma kapsamı',photo=false,sector=false}={}){return `<section class="expertise-hero ${photo?'expertise-hero-photo':''}"><div class="wrap expertise-hero-grid"><div class="expertise-hero-copy"><a class="expertise-back" href="${esc(back)}">← ${esc(backLabel)}</a><p class="eyebrow">${esc(label)}</p><h1>${esc(title)}</h1><p class="expertise-intro">${esc(description)}</p><a class="expertise-button" href="${esc(target)}">${esc(action)} ${arrow}</a></div><div class="expertise-hero-art">${photo?'<img src="/assets/brand/boraden-perspectives-v1.webp" alt="Boraden renkleriyle oluşturulmuş mimari kompozisyon" width="1672" height="941" fetchpriority="high">':fieldArt(group,sector)}</div></div></section>`;}
function serviceRows(services){return `<div class="service-rows service-choice-grid">${services.map((s,i)=>`<a href="${serviceURL(s)}" data-filter-text="${esc(s.title+' '+s.lead)}"><span class="choice-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.scope?.map(x=>x[0]).slice(0,3).join(' · ')||s.lead)}</p></div><span class="choice-arrow">${arrow}</span></a>`).join('')}</div>`;}
function catalogue(D){return `<div class="expertise-page">${expertiseHero('Hizmetlerimiz.','Vergi, denetim, danışmanlık, insan kaynakları, sistemler ve eğitim.',{label:'BORADEN / UZMANLIK',photo:true,back:'/insan/',backLabel:'Ana sayfa',target:'#hizmet-secimi',action:'Hizmetinizi bulun'})}<section class="wrap service-directory" id="hizmet-secimi"><div class="directory-heading"><div><p class="eyebrow">UZMANLIK ALANLARI</p><h2>Hangi konuda bilgi arıyorsunuz?</h2></div><label for="service-search">Hizmet arayın<input id="service-search" type="search" placeholder="Örn. vergi, denetim, bordro…"></label></div><p id="service-count" class="directory-count" aria-live="polite">${D.services.length} hizmet · ${D.groups.length} uzmanlık alanı</p>${D.groups.map((g,i)=>`<details id="grup-${g.id}" class="directory-field" data-filter-group style="--field-tone:${fieldColours[i%3]}"><summary><span class="field-thumb">${fieldArt(i)}</span><span><span class="eyebrow">0${i+1} / ${D.services.filter(s=>s.group===g.id).length} HİZMET</span><strong>${esc(g.name)}</strong></span><span class="disclosure-icon" aria-hidden="true">+</span></summary><div class="directory-field-body">${serviceRows(D.services.filter(s=>s.group===g.id))}<a class="text-link" href="${groupURL(g)}">${esc(g.name)} hakkında ${arrow}</a></div></details>`).join('')}</section></div>`;}
function groupPage(D,g){const i=D.groups.indexOf(g);return serviceScene(g.id,g.name,expertiseHero(g.name,g.description,{group:g.id,label:'0'+(i+1)+' / BORADEN UZMANLIĞI',target:'#hizmet-secimi',action:'Bu alandaki hizmetler'})+`<section class="wrap service-directory" id="hizmet-secimi"><div class="directory-heading"><div><p class="eyebrow">${D.services.filter(s=>s.group===g.id).length} HİZMET</p><h2>Çalışma alanları</h2></div><p>Kapsamı ve çalışma sürecini incelemek için bir hizmet seçin.</p></div>${serviceRows(D.services.filter(s=>s.group===g.id))}</section>`+serviceContact({group:g.id,title:g.name})+relatedGroups(D,g.id));}
function relatedGroups(D,group){return `<section class="related wrap"><p class="eyebrow">DİĞER ALANLAR</p><h2>İlgili uzmanlıklar</h2><div class="related-groups">${D.groups.filter(g=>g.id!==group).slice(0,3).map(g=>`<a href="${groupURL(g)}"><span class="expertise-index" style="--tone:${fieldColours[D.groups.indexOf(g)%3]}">${g.number}</span><span>${esc(g.name)}</span>${arrow}</a>`).join('')}</div></section>`;}
function servicePage(D,s){
 const g=D.groups.find(g=>g.id===s.group),description=s.definition||s.lead;
 const paragraphs=[...new Set([s.intro,s.explanation,s.lead,s.output].filter(t=>t&&t!==description&&!s.scope?.some(x=>x[1]===t)))];
 return serviceScene(s.group,s.title,expertiseHero(s.title,description,{group:s.group,label:g.name,back:groupURL(g),backLabel:g.name})+`
 <nav class="expertise-tabs wrap" aria-label="Bu hizmette"><a href="#kapsam">Çalışma kapsamı</a><a href="#yaklasim">İhtiyaç & süreç</a><a href="#hazirlik">Hazırlık & kaynaklar</a><a href="#hizmet-iletisim">İletişim ${arrow}</a></nav>
 <section class="service-scope wrap" id="kapsam"><header><p class="eyebrow">HİZMETİN İÇERİĞİ</p><h2>Çalışma kapsamı</h2><p>Başlıklara dokunarak ayrıntıları inceleyin.</p><div class="scope-signature" aria-hidden="true"><i></i><i></i><i></i></div></header><div class="scope-disclosures">${(s.scope||[]).map(([title,body],i)=>`<details class="scope-disclosure" name="service-scope"${i===0?' open':''}><summary><span class="scope-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(title)}</h3><span class="disclosure-icon" aria-hidden="true">+</span></summary><div class="scope-answer"><p>${esc(body)}</p></div></details>`).join('')}</div></section>
 <section class="service-needs" id="yaklasim"><div class="wrap"><div class="directory-heading"><div><p class="eyebrow">İHTİYAÇ & SÜREÇ</p><h2>Hangi durumlarda?</h2></div></div><div class="needs-grid">${(s.needs||[]).map((n,i)=>`<article><span class="needs-dot" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><h3>${esc(n)}</h3></article>`).join('')}</div>${s.steps?.length?`<ol class="service-steps">${s.steps.map(([t,b],i)=>`<li><span>0${i+1}</span><h3>${esc(t)}</h3><p>${esc(b)}</p></li>`).join('')}</ol>`:''}${paragraphs.length?`<details class="service-reading"><summary>Hizmetin yaklaşımı <span class="disclosure-icon" aria-hidden="true">+</span></summary><div>${paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div></details>`:''}</div></section>
 <section class="service-resources wrap" id="hazirlik"><header><p class="eyebrow">GÖRÜŞME ÖNCESİNDE</p><h2>Hazırlık ve bilgi</h2></header><div><details class="service-reading"><summary>İlk görüşmeye hazırlık <span class="disclosure-icon" aria-hidden="true">+</span></summary><div><ul class="prepare-list">${(s.prepare||['İhtiyacınızı ve çalışma amacınızı belirleyin.','Mevcut sürecinizi ve hedef takviminizi paylaşın.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="fine-print">Ayrıntılı dosya paylaşımını, çalışma için kararlaştırılan kanalda yürütürüz. İşlem ve dönem özelindeki kapsam, çalışma başlangıcında ayrıca değerlendirilir.</p></div></details>
 ${s.faqs?.length?`<details class="service-reading" id="sorular"><summary>Sık sorulan sorular <span class="disclosure-icon" aria-hidden="true">+</span></summary><div>${s.faqs.map(([q,a])=>`<details class="faq"><summary>${esc(q)}<span>+</span></summary><p>${esc(a)}</p></details>`).join('')}</div></details>`:''}
 ${s.legacyContent?.length?`<details class="service-reading"><summary>Tarihsel hizmet açıklaması <span class="disclosure-icon" aria-hidden="true">+</span></summary><div><p class="fine-print">Eski siteden korunan metindir. Mevzuat, tarihler ve kapsam bilgileri tarihsel bağlamıyla değerlendirilmelidir.</p>${s.legacyContent.map(t=>`<p>${esc(t)}</p>`).join('')}</div></details>`:''}
 ${s.sourceKeys?.length?`<details class="service-reading"><summary>Kaynaklar <span class="disclosure-icon" aria-hidden="true">+</span></summary><div>${sourceList(s.sourceKeys.map(k=>D.sources[k]))}</div></details>`:''}${s.note?`<p class="fine-print">${esc(s.note)}</p>`:''}</div></section><div id="hizmet-iletisim">${serviceContact({group:s.group,title:s.title,serviceId:s.id})}</div>`+relatedGroups(D,s.group));
}
function sectors(D){return `<div class="expertise-page">${expertiseHero('Sektör Raporları.','Sanayi, ihracat ve sektörel gelişmeler. Yayımlayan kurumlardan doğrulanan 2025–2026 raporları.',{label:'BORADEN / BİLGİ MERKEZİ',photo:true,back:'/insan/',backLabel:'Ana sayfa',target:'#sektor-raporlari',action:'Son raporları inceleyin'})}<section class="sector-archive" id="sektor-raporlari" data-card-flow><div class="wrap"><div class="directory-heading"><div><p class="eyebrow">2025 / 2026</p><h2>Son Raporlar</h2></div><p>Veri dönemi ve yayın tarihi ayrı belirtilir. Raporların tamamına doğrudan yayımlayan kurumdan ulaşabilirsiniz.</p></div><div class="archive-report-grid" data-flow-track tabindex="0" role="region" aria-label="Son raporlar">${D.sectorReports.map((r,i)=>`<a href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer"><span class="report-index" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="eyebrow">${esc(r.kind||'Rapor')} · VERİ DÖNEMİ · ${esc(r.period)}</span><h3>${esc(r.title)}</h3><p class="report-summary">${esc(r.summary)}</p><div class="report-meta"><span>${esc(r.publisher)}</span>${r.publishedAt?`<span>Yayın: <time datetime="${esc(r.publishedAt)}">${date(r.publishedAt)}</time></span>`:''}</div><span>Raporu kaynağında inceleyin ${arrow}<span class="sr-only"> — yeni sekmede açılır</span></span></a>`).join('')}</div><div class="flow-footer"><p>Üzerine gelerek durdurun veya oklarla ilerleyin.</p>${flowControls('Raporlar')}</div><p class="report-checked">Kaynak kontrolü: <time datetime="2026-09-17">17 Eylül 2026</time>. Bu raporlar ilgili kurumların yayınlarıdır.</p></div></section></div>`;}


function publicationPage(D,kind){return intro(kindNames[kind],kind==='blog'?'Finans, işletme yönetimi ve çalışma hayatı üzerine Boraden yazıları.':'Tarihleri ve kaynaklarıyla gündem; bilgiye doğrudan erişim.',{label:'BORADEN / BİLGİ & PERSPEKTİF'})+`<section class="wrap publication-list"><nav class="publication-nav">${Object.entries(kindNames).filter(([k])=>k!=='stories').map(([k,name])=>`<a href="/${kindPaths[k]}/" ${k===kind?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="journal-grid">${(D.publications[kind]||[]).filter(published).map(p=>journalCard(p,kind)).join('')||'<p>Yayınlanması onaylanmış içerikler bu alanda yer alacak.</p>'}</div>${kind==='circulars'?`<div class="archive-callout"><div><p class="eyebrow">BELGE ARŞİVİ</p><h2>Tarihî belge arşivi</h2><p>247 tarihî belge. Belgeler, ait oldukları dönemin koşullarıyla değerlendirilmelidir.</p></div>${btn('PDF arşivini açın','/arsiv/','button button-outline')}</div>`:''}</section>`;}
function articlePage(p,kind){if(kind!=='blog')return `<section class="reading-hero reading-brief wrap"><div><a class="text-link" href="/${kindPaths[kind]}/">← ${esc(kindNames[kind])}</a><p class="eyebrow">BORADEN / ${esc(p.category||kindNames[kind])}</p><h1>${esc(p.title)}</h1><p class="reading-lead">${esc(p.summary)}</p>${p.publicationDateVerified===true?`<p class="source-stamp">${publicationStamp(p)}</p>`:''}</div></section><div class="editorial-reading wrap"><nav class="reading-nav" aria-label="Yayın bağlantıları"><a href="#okuma">İçerik</a><a href="#kaynaklar">Kaynaklar</a><a href="/${kindPaths[kind]}/">Diğer yayınlar ↗</a></nav><article class="reading-body"><section id="okuma">${(p.body||[]).map((x,i)=>`<div class="reading-chapter"><span>0${i+1}</span><p>${esc(x)}</p></div>`).join('')}</section><section id="kaynaklar">${sourceList(p.sources)}</section></article></div>`;return `<section class="reading-hero wrap"><div><p class="eyebrow">BORADEN / ${esc(p.category)}</p><h1>${esc(p.title)}</h1><p class="reading-lead">${esc(p.summary)}</p><p class="source-stamp">${publicationStamp(p)}</p></div><div class="blog-detail-art">${p.cover?`<img src="${esc(safeURL('/'+p.cover.replace(/^\//,'')))}" alt="" width="960" height="960">`:artwork(p.service?.includes('bordro')?2:p.service?.includes('kurulus')?1:0)}</div></section><div class="editorial-reading wrap"><nav class="reading-nav" aria-label="Yazı bağlantıları"><a href="#okuma">Okuma notları</a><a href="#kaynaklar">Kaynaklar</a><a href="/blog/">Bütün yazılar ↗</a></nav><article class="reading-body"><section id="okuma">${(p.body||[]).map((x,i)=>`<div class="reading-chapter"><span>0${i+1}</span><p>${esc(x)}</p></div>`).join('')}</section><section id="kaynaklar">${sourceList(p.sources)}</section>${p.service?`<aside class="reading-service"><p class="eyebrow">İLGİLİ UZMANLIK</p>${btn('İlgili hizmeti inceleyin','/hizmetler/'+p.service+'/','text-link')}</aside>`:''}</article></div>`;}
function about(D){const a=D.about;return `<div class="company-profile">
<section class="company-profile-hero wrap"><div><p class="eyebrow">BORADEN / HAKKIMIZDA</p><h1>${esc(a.name)}</h1><p>${esc(a.foundation)}</p></div><div class="company-origin"><span>1993</span><p>Temellerimizin atıldığı yıl</p><div aria-hidden="true">${mark}</div></div></section>
<section class="company-introduction wrap"><p class="eyebrow">FAALİYET KAPSAMI</p><div><h2>Çalışma alanlarımız</h2><p>${esc(a.overview)}</p></div></section>
<nav class="company-scope wrap" aria-label="Boraden faaliyet alanları">${D.groups.map((g,i)=>`<a href="${groupURL(g)}" style="--field-tone:${['#00547c','#ad472c','#237341'][i%3]}"><span class="company-field-number">0${i+1}</span><div><h3>${esc(g.name)}</h3><p>${esc(a.scope[g.id])}</p></div>${arrow}</a>`).join('')}</nav>
<section class="company-audiences wrap"><h2>Hangi ihtiyaçlarda başvurulur?</h2><ul><li>Şirket kuruluşu, ticaret sicili işlemleri ve şirket değerlemesi.</li><li>Denetim, vergi, muhasebe, finansal raporlama, bordro ve çalışma hayatı süreçleri.</li><li>Mali ve hukuki danışmanlık, sözleşme ve tahsilat süreçleri; sistem kurulumu, veri analizi ve eğitim.</li></ul></section>
<section class="company-process wrap" aria-label="Çalışma süreci"><article><p class="eyebrow">01 / İHTİYAÇ</p><h3>İhtiyacın belirlenmesi</h3><p>Kurumun faaliyetleri, mevcut süreçleri ve çalışmanın amacı değerlendirilir.</p></article><article><p class="eyebrow">02 / KAPSAM</p><h3>Kapsamın belirlenmesi</h3><p>İlgili hizmetler, gerekli bilgi ve belgeler ile çalışma kapsamı belirlenir.</p></article><article><p class="eyebrow">03 / ÇALIŞMA</p><h3>Çalışmanın yürütülmesi</h3><p>İlgili uzmanlık alanları kapsam doğrultusunda birlikte ele alınır; bulgular ve değerlendirmeler paylaşılır.</p></article></section>
<section class="company-method wrap"><div><p class="eyebrow">ÇALIŞMA BİÇİMİ</p><h2>Kapsam ve ilkeler</h2><p>${esc(a.method)}</p></div><dl>${a.principles.map(([title,text])=>`<div><dt>${esc(title)}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl></section>
<nav class="quick-links wrap" aria-label="Kurumsal sayfalar"><a href="/misyon-vizyon/">Misyon & vizyon ${arrow}</a><a href="/ekibimiz/">Ekibimiz ${arrow}</a><a href="/kariyer/">Kariyer ${arrow}</a></nav></div>`;}

function contact(){return intro('İletişim.','Hizmet kapsamı ve çalışma süreci hakkında bilgi almak için Boraden’e ulaşabilirsiniz.',{label:'BORADEN / İLETİŞİM',group:'boraden'})+`<section class="contact-grid wrap"><div><p class="eyebrow">TELEFON VE E-POSTA</p><a class="contact-large" href="mailto:info@boraden.com.tr">info@boraden.com.tr</a><a class="contact-large" href="tel:+902124832611">+90 (212) 483 26 11</a>${btn('WhatsApp üzerinden ulaşın','https://wa.me/905532380335','text-link')}</div><div><p class="eyebrow">OFİSİMİZ</p><h2>İstanbul</h2><p>Maltepe Mahallesi, Yedikule Çırpıcı Yolu Sokak<br>Avrupa Kale Ofis Blok, No: 2, Kat: 2, Daire: 5<br>34010 Zeytinburnu, İstanbul</p></div></section>`;}
function archive(L){return intro('Belge arşivi.','Tarihî belge arşivi. Eski mevzuat ve tarihler güncel uygulama olarak değerlendirilmemelidir.',{label:'BORADEN / 247 PDF'})+`<section class="wrap archive-list"><label for="archive-search">Belge arayın<input id="archive-search" type="search" placeholder="Başlık veya yıl…"></label><p class="archive-count" aria-live="polite">247 belge</p>${L.documents.map(d=>`<a data-filter-text="${esc((d.title||d.id)+' '+(d.date||d.year||''))}" href="${esc(d.file)}" target="_blank" rel="noopener"><span><strong>${esc(d.title||d.id)}</strong><small>${esc(d.date||d.year||'Tarih doğrulanmadı')} · Tarihî belge · PDF</small></span>${arrow}</a>`).join('')}</section>`;}
function perspectives(D){return intro('Dünyadan perspektifler.','Ekonomi, yönetim ve çalışma hayatı üzerine kaynaklarıyla birlikte okuma notları.',{label:'DÜNYADAN PERSPEKTİFLER'})+`<section class="perspective-gallery wrap">${D.perspectives.map(p=>`<a href="/perspektifler/${esc(p.id)}/"><img src="/assets/thinkers/${esc(p.image)}.jpg" alt="${esc(p.person)}" loading="lazy" width="480" height="560"><p class="eyebrow">${esc(p.topic)}</p><h2>${esc(p.person)}</h2><h3>${esc(p.title)}</h3><p>${esc(sourceDateLabel(p))} ↗</p></a>`).join('')}</section>`;}
function careerPage(){return intro('Boraden’de kariyer.','Çalışma alanları ve genel başvuru süreci hakkında bilgi.',{label:'BORADEN / KARİYER',group:'boraden'})+`<section class="career-layout wrap"><div><p class="eyebrow">BAŞVURU SÜRECİ</p><h2>Genel başvuru bilgileri</h2><p>Deneyiminizi, ilgi duyduğunuz uzmanlık alanını ve çalışma yaklaşımınızı paylaşabileceğiniz bir başlangıç.</p><ol class="career-steps"><li><strong>01 / Kendinizi anlatın</strong><span>Deneyiminiz ve ilgilendiğiniz alan.</span></li><li><strong>02 / Perspektifinizi paylaşın</strong><span>Çalışmalara nasıl bir katkı sunmak istersiniz?</span></li><li><strong>03 / Birlikte değerlendirelim</strong><span>Uygun ihtiyaçlar için görüşme.</span></li></ol></div><div class="career-form"><h2>Genel başvuru</h2><p class="career-notice">Başvuru alanı hazırlanmaktadır. Bu önizleme kişisel bilgi toplamaz; şu anda açık pozisyon ilanı değildir.</p><fieldset disabled><legend class="sr-only">Başvuru alanı — henüz aktif değil</legend><label>Ad Soyad<input type="text" placeholder="Adınız ve soyadınız"></label><label>E-posta<input type="email" placeholder="E-posta adresiniz"></label><label>İlgilendiğiniz alan<select><option>Uzmanlık alanı seçin</option><option>Denetim ve raporlama</option><option>Vergi ve mali müşavirlik</option><option>Danışmanlık</option><option>İnsan kaynakları ve bordro</option></select></label><label>Kısaca siz<textarea rows="3" placeholder="Deneyiminiz ve ilgi alanlarınız"></textarea></label><div class="career-upload">Özgeçmiş · PDF</div><button type="button" disabled>Başvurular henüz açılmadı</button></fieldset></div></section>`;}
function simplePage(name){if(name==='kariyer')return careerPage();const entries={
 'kariyer':['Bakışını kat. Birlikte ilerleyelim.','Kendinizi, çalışmak istediğiniz alanı ve Boraden’e katabileceğiniz perspektifi anlatın.','Bu alan açık pozisyon ilanı değildir. Genel başvuru formu ve Wagtail üzerinden atanacak kişiye e-posta bildirimi sonraki entegrasyon aşamasında bağlanacaktır. Bu tasarım önizlemesi başvuru toplamaz.'],
 'ekibimiz':['Birlikte, Boraden.','Ekip profilleri yayın onayının ardından bu alanda yer alacak.','Unvanlar, uzmanlık alanları ve profil bilgileri onaylandıktan sonra ekip yapısı burada yayınlanacaktır.'],
 'misyon-vizyon':['Misyon ve vizyon.','Misyon & vizyon',''],
 'yayin-ilkeleri':['Yayın ilkeleri.','Kaynak, tarih ve kapsam her bilginin parçasıdır.','Tarihî bir belge güncel başvuru imkânı olarak sunulmaz. Temsili görseller çalışan veya müşteri fotoğrafı olarak sunulmaz. Hesaplama araçlarının parametre ve sınırları ilgili sayfada açıklanır.'],
 'basari-hikayeleri':['Her iş birliğinin bir hikâyesi var.','Onaylı müşteri çalışmaları bu bölümde yer alacak.','Müşteri isimleri veya başarı sonuçları uydurulmaz.']};const p=entries[name]||['Bilgi havuzumuz.','Önceki sürümün içerik ve belgeleri korundu.',''];return intro(p[0],p[1],{label:'BORADEN / KURUMSAL'})+`<section class="article wrap"><p>${esc(p[2])}</p>${name==='misyon-vizyon'?'<h2>Misyonumuz</h2><p>İşletmelerin ihtiyaçlarını doğru anlamak; denetim, vergi, finans, insan ve veri disiplinlerini açık, uygulanabilir ve güvenilir bir çalışma çerçevesinde bir araya getirmek.</p><h2>Vizyonumuz</h2><p>Deneyimini teknoloji ve yeni çalışma biçimleriyle geliştiren; işletmelerin kararlarına uzun vadeli değer katan bir danışmanlık markası olmak.</p>':''}${btn('Boraden ile iletişime geçin','/iletisim/','text-link')}</section>`;}
function calculations(mode){
 if(mode){const info=calculators.calculatorInfo[mode];let body=calculators.calculator(mode);body=body.slice(body.indexOf('<section class="section-pad calculator-workspace">')).replace(/href="([^"]+)"/g,(match,href)=>{href=href.replaceAll('&amp;','&');if(href.startsWith('assets/'))return 'href="/'+href+'"';if(!href.startsWith('?'))return match;const params=new URLSearchParams(href.slice(1));if(params.has('service'))return 'href="/hizmetler/'+esc(params.get('service'))+'/"';if(params.get('page')==='hesaplama')return 'href="/hesaplama/'+Object.keys(calculatorModes).find(k=>calculatorModes[k]===params.get('calc'))+'/"';if(params.get('page')==='iletisim')return 'href="/iletisim/"';return match;});const steps={income:['Matrah','Dilimler','Toplam vergi'],vat:['Net tutar','KDV','Toplam'],salary:['Brüt ücret','Kesintiler','Net ücret']}[mode];
 body=body.replace('aria-label="Hesaplama türü">','aria-label="Hesaplama türü"><a href="/hesaplama/">Tüm hesaplamalar</a><a href="/insan/araclar/#arac-amortisman">Otomobil amortismanı</a>');
 body=body.replace('<section class="calculator-intro-guide section-pad">','<section class="calculator-intro-guide section-pad"><div class="calc-guide-copy">').replace('</a></section><section class="matrah-section',`</a></div><div class="calc-guide-visual" aria-label="${steps.join(' → ')}"><span class="calc-diagram-label">${mode==='income'?'DİLİM DİLİM':mode==='vat'?'TUTARIN BİLEŞENLERİ':'BRÜTTEN NETE'}</span><div class="calc-steps">${steps.map((step,i)=>`<div class="calc-step"><span aria-hidden="true">0${i+1}</span><strong>${step}</strong></div>`).join('')}</div><span class="calc-diagram-note">Şematik gösterim · Açıklamayı inceleyin</span></div></section><section class="matrah-section`).replace('<span aria-hidden="true">7326</span>','<div class="calc-archive-visual" aria-hidden="true"><div class="calc-document"><span>MEVZUAT ARŞİVİ</span><strong>7326</strong><span>2021 / HESAPLAMA DOSYASI</span><i></i><i></i><i></i><b>XLSX ↗</b></div></div>');
 return intro(info.name,info.lead,{label:'BORADEN / HESAPLAMA · 2026'})+'<div class="calculator-shell wrap" data-calculator-kind="'+mode+'">'+body+'</div>';}
 return '<div class="calculation-index">'+intro('Hesaplama araçları.','Binek otomobil amortismanı, gelir vergisi, KDV ve brüt/net ücret. Yöntemi ve kaynakları görünür, tarayıcınızda çalışan hesaplama araçları.',{label:'BORADEN / HESAPLAMA'})+`<section class="wrap detail-body"><div class="quick-links calculation-options"><a href="/insan/araclar/#arac-amortisman">Binek otomobil amortismanı ${arrow}</a><a href="/hesaplama/gelir-vergisi/">Gelir vergisi ${arrow}</a><a href="/hesaplama/kdv/">KDV ${arrow}</a><a href="/hesaplama/brut-net-maas/">Brüt / net ücret ${arrow}</a></div><div class="archive-callout"><div><p class="eyebrow">TARİHÎ KAYNAK / 2021</p><h2>7326 hesaplama dosyası</h2><p>Bu dosya 2021 düzenlemesine aittir; güncel başvuru veya matrah artırımı imkânı değildir.</p></div>${btn('Excel dosyasını indirin','/assets/documents/7326-Hesaplama-2021.xlsx','button button-outline')}</div></section></div>`;
}
function perspectivePage(D,p){const service=D.services.find(s=>s.id===p.service),thinker=D.thinkers.find(t=>t.perspective===p.id);return `<section class="reading-hero wrap"><div><p class="eyebrow">DÜNYADAN PERSPEKTİFLER / ${esc(p.person)}</p><h1>${esc(p.title)}</h1><p class="reading-lead">${esc(p.summary)}</p><p class="source-stamp">${esc(sourceDateLabel(p))}</p></div>${thinker?portrait(thinker):''}</section><div class="editorial-reading wrap"><nav class="reading-nav" aria-label="Bu okumada"><a href="#fikrin-kaynagi">Fikrin kaynağı</a><a href="#isiniz-icin">İşiniz için anlamı</a><a href="#karara-tasiyin">Karara taşıyın</a><a href="/perspektifler/">Tüm perspektifler ↗</a></nav><article class="reading-body"><div class="reading-quote"><blockquote>${esc(p.quote)}</blockquote><p>${esc(p.quoteLabel||'Kaynak temelli editoryal özet')}</p></div><section id="fikrin-kaynagi"><p class="eyebrow">01 / KAYNAK</p><h2>${esc(p.sourceTitle||'Düşüncenin bağlamı')}</h2><p>${esc(p.intro)}</p><p>${esc(p.bio)}</p><p>${esc(p.sourceSummary)}</p>${sourceList([[p.sourceTitle||'Orijinal kaynak',p.source]])}</section><section id="isiniz-icin"><p class="eyebrow">02 / BORADEN PERSPEKTİFİ</p>${(p.sections||[]).map(([h,t],i)=>`<div class="reading-chapter"><span>0${i+1}</span><div><h2>${esc(h)}</h2><p>${esc(t)}</p></div></div>`).join('')}</section><section id="karara-tasiyin"><div class="reading-takeaway"><p class="eyebrow">03 / AKLINIZDA KALSIN</p><h2>Karara taşırken.</h2><p>${esc(p.takeaway)}</p></div><ul class="prepare-list">${(p.questions||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ul>${service?`<aside class="reading-service"><p class="eyebrow">İLGİLİ UZMANLIK</p><h3>${esc(service.title)}</h3>${btn('Bu konuda nasıl yardımcı oluyoruz?',serviceURL(service),'text-link')}</aside>`:''}</section><p class="fine-print">Bu okuma kişi veya kurumun Boraden ile iş ilişkisi veya marka onayı anlamına gelmez.</p></article></div>`;}
export function routeList(D){return ['/', '/hizmetler/','/sektorler/','/hakkimizda/','/biz-kimiz/','/iletisim/','/kariyer/','/ekibimiz/','/misyon-vizyon/','/yayin-ilkeleri/','/hesaplama/',...Object.keys(calculatorModes).map(k=>'/hesaplama/'+k+'/'),'/arsiv/','/perspektifler/',...D.groups.map(groupURL),...D.services.map(serviceURL),...D.sectors.map(s=>'/sektorler/'+s.id+'/'),...Object.values(kindPaths).map(k=>'/'+k+'/'),...Object.entries(D.publications).flatMap(([kind,list])=>list.filter(published).map(p=>'/'+kindPaths[kind]+'/'+p.id+'/')),...D.perspectives.map(p=>'/perspektifler/'+p.id+'/')];}
export function render(url,D,L){const p=url.split('/').filter(Boolean);let body,title='Boraden — Her parça uzmanlık. Birlikte, Boraden.';
 if(!p.length)body=home(D);
 else if(p[0]==='hizmetler'&&p.length===1){body=catalogue(D);title='Hizmetlerimiz | Boraden';}
 else if(p[0]==='hizmetler'&&p[1]==='alan'){const g=D.groups.find(g=>g.id===p[2]);if(g){body=groupPage(D,g);title=g.name+' | Boraden';}}
 else if(p[0]==='hizmetler'){const s=D.services.find(s=>s.id===p[1]);if(s){body=servicePage(D,s);title=s.seoTitle||s.title+' | Boraden';}}
 else if(p[0]==='sektorler'){body=sectors(D);title='Sektör Raporları | Boraden';}
 else if(p[0]==='hakkimizda'||p[0]==='biz-kimiz'){body=about(D);title='Hakkımızda | Boraden';}
 else if(p[0]==='iletisim'){body=contact();title='İletişim | Boraden';}
 else if(p[0]==='arsiv'){body=archive(L);title='PDF Arşivi | Boraden';}
 else if(p[0]==='hesaplama'){if(!p[1]||Object.hasOwn(calculatorModes,p[1])){body=calculations(calculatorModes[p[1]]);title=(calculators.calculatorInfo[calculatorModes[p[1]]]?.name||'Hesaplama Merkezi')+' | Boraden';}}
 else if(p[0]==='perspektifler'){const per=D.perspectives.find(x=>x.id===p[1]);body=per?perspectivePage(D,per):perspectives(D);title=(per?.title||'Dünyadan Perspektifler')+' | Boraden';}
 else {const kind=Object.keys(kindPaths).find(k=>kindPaths[k]===p[0]);if(kind){const post=D.publications[kind].find(x=>x.id===p[1]&&published(x));body=post?articlePage(post,kind):publicationPage(D,kind);title=(post?.title||kindNames[kind])+' | Boraden';}else if(['kariyer','ekibimiz','misyon-vizyon','yayin-ilkeleri'].includes(p[0])){body=simplePage(p[0]);title=p[0].replaceAll('-',' ')+' | Boraden';}}
 const status=body?200:404;if(!body){body=intro('Bu parça burada değil.','Aradığınız sayfayı hizmetlerimizden veya aramadan bulabilirsiniz.')+`<div class="wrap error-link">${btn('Ana sayfaya dönün','/')}</div>`;title='Sayfa bulunamadı | Boraden';}
 return {status,title,html:`<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Boraden: denetim, vergi, danışmanlık, insan kaynakları ve veri alanlarında birbirini tamamlayan uzmanlıklar."><meta name="theme-color" content="#f8f8f3"><title>${esc(title)}</title><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/font-2.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/home-media.css"><link rel="stylesheet" href="/brand-theme.css">${!p.length?'<link rel="stylesheet" href="/home-motion.css">':''}${p[0]==='hizmetler'?'<link rel="stylesheet" href="/service-contact.css">':''}${!p.length?'<script src="/section-video.js" defer></script>':''}<script src="/app.js" type="module"></script>${p[0]==='hesaplama'&&p[1]?'<script src="/calculator-core.js" defer></script><script src="/calculator-ui.js" defer></script>':''}<link rel="stylesheet" href="/insan/discovery.css"><script type="module" src="/insan/discovery.js"></script><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/insan/editorial-design.css">${p[0]==='sektorler'?'<script type="module" src="/insan/editorial.js"></script>':''}${['hizmetler','sektorler'].includes(p[0])?'<link rel="stylesheet" href="/service-motion.css">':''}</head><body class="${p.length?'interior':'home'}${p[0]==='sektorler'?' sector-theme':''}">${header(D)}<main id="main">${body}</main>${footer()}${search(D)}</body></html>`};
}
